-- ====================================================================
-- SCRIPT: 03_load_data.sql
-- PROJECT: New Wheels Sales Analytics — Automotive / Transportation
-- DESCRIPTION: Standalone DML batch loading script for all entities
-- ====================================================================

USE new_wheels_db;

SET foreign_key_checks = 0;





















































SET foreign_key_checks = 1;

-- Verification row counts
SELECT "dispatch_centers" AS entity, COUNT(*) AS total_records FROM dispatch_centers
UNION ALL SELECT "carriers", COUNT(*) FROM carriers
UNION ALL SELECT "customers", COUNT(*) FROM customers
UNION ALL SELECT "vehicles", COUNT(*) FROM vehicles
UNION ALL SELECT "orders", COUNT(*) FROM orders
UNION ALL SELECT "order_items", COUNT(*) FROM order_items
UNION ALL SELECT "shipping", COUNT(*) FROM shipping
UNION ALL SELECT "customer_feedback", COUNT(*) FROM customer_feedback;
